    static boolean hasPrecedence(char operator1, char operator2)
    {
        return (operator1 != '*' && operator1 != '/') || (operator2 != '+' && operator2 != '-');
    }
    
    static double applyOperator(char operator, double b, double a)
    {
        switch(operator)
        {
            case '+':
            {
                return a + b;
            }
            
            case '-':
            {
                return a - b;
            }
            
            case '*':
            {
                return a * b;
            }
            
            case '/':
            {   
                
                
                return a / b;
            }
        }
        
        return 0;
    }
    
